import type en from '../en/help';
import type { Translation } from '../types';

export default {
  'help.menu': 'Scope-Hilfe einblenden',
  'help.open': 'Was ist {scope}?',
  'help.none': 'Für diese Ansicht gibt es noch keinen Hilfetext.',
  'help.read': 'So liest man es',
  'help.try': 'Ausprobieren',
  'help.checkPrefix': 'Geschafft, wenn:',
  'help.done': 'Ausprobiert',
  'help.progress': '{done} von {all} Aufgaben ausprobiert',
  'help.pitfall': 'Achtung:',
  // --- scope texts (sources and checks: docs/research/scope-hilfe.md) ---
  'help.picture.one': "Das Quellbild, wahlweise mit Overlay: Falschfarben, Zebra, Clipping, Hautton, Grün, Luma, Gamut, EBU R 103, Neutral oder Fokus-Peaking.",
  'help.picture.what': "Erste Kontrolle, ob Bild, Schärfe und Ausschnitt stimmen, und Belichtung direkt im Bild prüfen. Zebra und Falschfarben zeigen, wo Lichter clippen oder Haut liegt, ohne den Blick vom Motiv zu nehmen. Ein Klick setzt einen Messpunkt, ein gezogener Rahmen einen Messbereich für alle Scopes; Rechtsklick löscht.",
  'help.picture.read': "Overlay Zebra: Streifen auf allem, dessen Luma Y′ den eingestellten Pegel erreicht (Vorgabe 95 %).\nFalschfarben (Paletten ARRI, Belichtung, RED Video, Sony SDR, Sony S-Log3) färben Pegelbänder; die Legende unten links nennt die Bänder der gewählten Palette.\nGamut-Warnung: Pixel mit negativen Anteilen im Zielgamut (709/P3/2020), in drei Stufen gelb/orange/magenta.\nOverlay „EBU R 103“: gelb = außerhalb −5/105 %, rot = außerhalb des Gesamtbereichs (Codes 4–1019).\nGut: Zebra nur auf Spitzlichtern, nicht auf Gesichtern oder großen Flächen.",
  'help.picture.try': "Testbild „SMPTE 75 % Balken + PLUGE“, im ⚙ Overlay „Zebra“, Pegel 95 % (Vorgabe).",
  'help.picture.check': "Streifen erscheinen nur auf dem 100-%-Weißfeld unten, nicht auf dem 75-%-Grau oben links.",
  'help.picture.pitfall': "Das Bild zeigt das Signal über den Display-Farbraum des Rechners; Monitor-Helligkeit sagt nichts über den Pegel. Gemessen wird immer das Signal.",
  'help.wf-luma.one': "Helligkeit (Y′) jedes Pixels, von links nach rechts wie im Bild.",
  'help.wf-luma.what': "Das Grundwerkzeug für Belichtung, Schwarz- und Weißpegel. Beim Shading stellt man hier Iris und Master Black (Pedestal) ein und vergleicht Kameras auf einem Graukeil. Für die Legalität zeigt sie, ob Pegel über 100 % oder unter 0 % gehen.",
  'help.wf-luma.read': "Waagerecht: Bildposition links → rechts; senkrecht: Pegel −7 … 110 % (Skala auch 8/10 bit, cd/m²).\n0 % = Schwarz (Code 64 bei 10 bit), 100 % = Nennweiß (Code 940).\nLupen: Schwarz-Lupe −5 … 15 %, Lichter-Lupe 85 … 110 %.\nOptional Grenzlinien −5/105 % (EBU R 103); Marken bei HDR 75 % HLG / 58 % PQ Referenzweiß und 38 % Graukarte, bei Log 18 % Grau.\nGut: Schwarz knapp über 0 %, Weiß bei ≤ 100 %, Graukeil als gleichmäßige Treppe.",
  'help.wf-luma.try': "Testbild „SMPTE 75 % Balken + PLUGE“, Lupe „voll“; danach im ⚙ Lupe „Schwarz-Lupe“.",
  'help.wf-luma.check': "In voller Ansicht stehen die Balken bei 75,0 / 69,6 / 59,1 / 53,6 / 21,4 / 15,9 / 5,4 %; in der Schwarz-Lupe zeigt das PLUGE-Feld rechts unten +2 % und +4 % als zwei Stufen über 0 %.",
  'help.wf-luma.pitfall': "Hautton „auf 70 IRE“ ist eine Faustregel, kein Normwert; das Publikum sieht das Bild, nicht die Waveform. Für SDR gibt es keinen genormten Hautpegel.",
  'help.wf-color.one': "Luma-Waveform, jeder Punkt in seiner Bildfarbe.",
  'help.wf-color.what': "Zeigt auf einen Blick, welche Bildteile welchen Pegel haben – nützlich, wenn mehrere Objekte auf ähnlicher Höhe liegen (z. B. Gesicht vor heller Wand). Ersetzt beim schnellen Belichten oft den Wechsel zwischen Bild und Waveform.",
  'help.wf-color.read': "Achsen und Skala wie Waveform Luma.\nFarbe = Pixelfarbe (Helligkeit angeglichen, damit dunkle Pixel sichtbar bleiben), Höhe = Luma; Farbe verändert die Messung nicht.\nGut: das wichtige Objekt (Gesicht, Logo) ist an seiner Farbe erkennbar und liegt im gewünschten Band.",
  'help.wf-color.try': "Testbild „SMPTE 75 % Balken + PLUGE“.",
  'help.wf-color.check': "Der gelbe Balken erscheint gelb bei 69,6 %, der blaue blau bei 5,4 %.",
  'help.wf-color.pitfall': "Farbe heißt nicht Kanalpegel: ein roter Punkt bei 16 % bedeutet Luma 16 %, nicht R′ = 16 %. Für Kanäle die RGB-Parade nehmen.",
  'help.wf-skin.one': "Luma-Waveform, in der nur Hauttöne farbig sind, der Rest grau.",
  'help.wf-skin.what': "Findet Gesichter in der Waveform, auch in vollen Bildern, und zeigt, ob sie zwischen Kameras auf gleicher Höhe liegen. Hilft beim Racking von Moderation und Talk, wo Haut das wichtigste Bildelement ist.",
  'help.wf-skin.read': "Band mit zwei Linien = Luma-Bereich (Vorgabe 30–80 %), Linien ziehen verstellt ihn; Mausrad = Farbton-Toleranz um die Hautton-Linie 123° (Vorgabe ±14°).\nFarbig erscheinen nur Pixel innerhalb von Luma-Bereich und Farbton-Toleranz, alle anderen grau.\nDas Vectorscope zeigt dazu den Toleranzkeil um die Hautton-Linie.\nBereich auch per ⚙ „Bereich aus Messrahmen“ übernehmbar (vorher Rahmen im Bild aufs Gesicht ziehen).\nGut: farbige Punkte gebündelt, bei mehreren Kameras auf ähnlicher Höhe.",
  'help.wf-skin.try': "Testbild „ColorChecker (Näherung)“, Vorgaben unverändert.",
  'help.wf-skin.check': "Die beiden Hautfelder (obere Reihe, Feld 1 und 2) erscheinen farbig; Blau-, Grün-, Cyan- und Graufelder bleiben grau. Das Feld Orange liegt knapp an der Toleranzgrenze und kann mitgefärbt sein.",
  'help.wf-skin.pitfall': "Feste Hautpegel gibt es nur für HDR. Für SDR sind Werte wie „70–80 IRE“ Erfahrungswerte aus der NTSC-Zeit, keine Norm.",
  'help.wf-green.one': "Luma-Waveform, die nur Grüntöne (Rasen, Laub) farbig zeigt.",
  'help.wf-green.what': "Sport und Außenübertragung: Rasen soll über alle Kameras gleich hell und gleich grün wirken. Zeigt Pegel und Lage des Grüns, ohne dass Trikots oder Werbebanden stören.",
  'help.wf-green.read': "Band = Luma-Bereich des Grün-Qualifiers (Vorgabe 40–55 %), Linien ziehen verstellt ihn; Farbton 198° ± 20° (Vorgabe), Mausrad = Toleranz. Im Vectorscope als „Grün-Keil“ einblendbar.\nGut: Rasenpunkte als enges Band, bei allen Kameras auf gleicher Höhe.",
  'help.wf-green.try': "Testbild „ColorChecker (Näherung)“; die untere Band-Linie von 40 % auf etwa 35 % ziehen.",
  'help.wf-green.check': "Vorher ist kein Feld farbig (Laub liegt bei 39,4 % Luma), danach erscheint nur das Feld Laub (obere Reihe, Feld 4) farbig.",
  'help.wf-green.pitfall': "Die Vorgabe 40–55 % stammt aus BT.2408 für HLG-HDR; für SDR gibt es keinen Normwert. Unter LED-Flutlicht kann der Farbton wandern.",
  'help.wf-rgb.one': "R′, G′ und B′ übereinander in einer Waveform.",
  'help.wf-rgb.what': "Schneller Neutralitäts-Check: Bei Grau und Weiß müssen alle drei Kanäle deckungsgleich sein. Beim Weiß- und Schwarzabgleich sieht man sofort, welcher Kanal vorsteht.",
  'help.wf-rgb.read': "Achsen wie Waveform Luma; drei Spuren in Kanalfarben (mono/Bildfarben wählbar), Kanäle einzeln abschaltbar.\nWo sich alle drei decken, entsteht Weiß = neutral.\nGut: Graukeil als eine weiße Treppe ohne farbige Säume.",
  'help.wf-rgb.try': "Testbild „Graustufen 11 (0–100 %)“.",
  'help.wf-rgb.check': "Jede Stufe erscheint als eine weiße Linie, kein roter, grüner oder blauer Rand.",
  'help.wf-rgb.pitfall': "Bei bunten Bildern überlagern sich die Spuren und verdecken sich; zum Einstellen einzelner Kanäle die Parade nehmen.",
  'help.parade.one': "R′, G′ und B′ nebeneinander, je ein Drittel der Breite.",
  'help.parade.what': "Das Hauptwerkzeug für Weiß-/Schwarzabgleich und Shading: Auf einer Graukarte oder einem Graukeil müssen die drei Kanäle gleich hoch stehen. White Shading (Saw/Par) stellt man kanalweise so ein, dass jede Spur flach wird. Mit *Touch Shading* (Kamera über lz-camera-bridge oder Simulator) lassen sich Black und White je Kanal direkt hier ziehen.",
  'help.parade.read': "Drei Felder R | G | B, jedes mit Bildposition links → rechts und Pegel −7 … 110 %.\nGleiche Höhe in allen drei Feldern = neutral (Grau/Weiß).\nFlache Spur auf gleichmäßiger Weißfläche = Shading in Ordnung; Bogen = Hotspot/Randabfall, Schräge = Saw-Fehler.\nGut: Schwarz aller Kanäle auf gleicher Höhe knapp über 0 %, Weiß gleich hoch.",
  'help.parade.try': "Testbild „SMPTE 75 % Balken + PLUGE“.",
  'help.parade.check': "In R stehen Grau, Gelb, Magenta, Rot auf 75 % und Cyan, Grün, Blau auf 0 %; G und B entsprechend (G: Grau, Gelb, Cyan, Grün; B: Grau, Cyan, Magenta, Blau).",
  'help.parade.pitfall': "Black Balance mit ganz hochgezogenem Pedestal verfälscht den Abgleich; Pedestal nur so weit anheben, dass nichts clippt. Weißabgleich auf Papier mit Aufheller oder unter ungleichmäßigem Licht verfälscht alle Kanäle. Graukarten sind nicht immer neutral.",
  'help.yrgb.one': "Luma und R′, G′, B′ nebeneinander in vier Feldern.",
  'help.yrgb.what': "Verbindet Belichtung (Y′) und Kanalbalance in einer Ansicht – praktisch beim Shading, wenn man Iris/Pedestal und Farbbalance gleichzeitig führt.",
  'help.yrgb.read': "Felder Y | R | G | B, Skala wie Waveform Luma.\nY′ zeigt die Helligkeit, R/G/B die Balance; bei Grau alle vier gleich hoch.\nGut: Graukarte in allen vier Feldern auf gleicher Höhe.",
  'help.yrgb.try': "Testbild „Grau 50 %“.",
  'help.yrgb.check': "Alle vier Spuren liegen als flache Linie bei 50 %.",
  'help.yrgb.pitfall': "Y′ ist gewichtet (Grün zählt 71,5 %, Blau 7,2 % bei BT.709); ein blauer Fehler fällt im Y-Feld kaum auf, nur im B-Feld.",
  'help.ycbcr.one': "Luma Y′ und die Farbdifferenzen Cb und Cr nebeneinander.",
  'help.ycbcr.what': "Zeigt das Signal so, wie es auf SDI übertragen wird. Grau muss in Cb und Cr genau auf der Nulllinie liegen; Abweichung = Farbstich. Klassische Ansicht für „Camera Line up / Racking YCrCb“.",
  'help.ycbcr.read': "Y′-Feld wie Waveform Luma; Cb und Cr sind um 50 % versetzt auf derselben Skala gezeichnet, die 50-%-Linie ist ihr Nullpunkt.\nOberhalb von 50 %: Cb = Richtung Blau, Cr = Richtung Rot; unterhalb: Gelb bzw. Cyan/Grün.\nGut: alle neutralen Flächen exakt auf der 50-%-Linie von Cb und Cr.",
  'help.ycbcr.try': "Testbild „Graustufen 11 (0–100 %)“.",
  'help.ycbcr.check': "Cb und Cr sind über die ganze Breite eine flache Linie bei 50 % (= 0), Y′ eine Treppe von 0 bis 100 %.",
  'help.ycbcr.pitfall': "HD- und SD-Signale sehen bei gleichen Balken in Y′ und Cb/Cr verschieden aus (andere Matrix BT.709 vs. BT.601) – das ist kein Fehler.",
  'help.vector.one': "Farbton als Winkel, Farbsättigung als Abstand von der Mitte (Cb waagerecht, Cr senkrecht).",
  'help.vector.what': "Prüft Farbbalken, Weißabgleich und Matrix-Einstellungen und vergleicht Kameras farblich. Weiß und Grau gehören in die Mitte; jeder Versatz ist ein Farbstich. Beim White Shading zeigt hohe Verstärkung, ob die Weißfläche als kleiner Punkt in der Mitte liegt.",
  'help.vector.read': "Kästchen = 75-%-Ziele, kleine Kreise = 100-%-Ziele (nur bei ×1), passend zur Matrix der Quelle.\nGestrichelte Linie = Hautton-Linie (123°), mit Toleranzkeil der Hautton-Waveform.\nZoom ×1/×2/×5; Ziele außerhalb erscheinen als Dreieck am Rand, oben rechts „×2 ZOOM“ bzw. „×5 ZOOM“.\nIm ⚙ einblendbar: Gamut-Grenzen 709/P3/2020, Grün-Keil, eigene Farbziele.\nGut: Balkenpunkte in den Kästchen, Grau als Punkt in der Mitte.",
  'help.vector.try': "Testbild „SMPTE 75 % Balken + PLUGE“, Zoom ×1.",
  'help.vector.check': "Die sechs Farbpunkte liegen in den sechs 75-%-Kästchen; Grau, Weiß und Schwarz bilden einen Punkt in der Mitte. (Zwei zusätzliche Punkte außerhalb der Kästchen stammen von −I und +Q aus der unteren Reihe.) Winkel zur Kontrolle (Teilstriche alle 10°, 0° = +Cb rechts, gegen den Uhrzeigersinn): Gelb ≈ 175°, Rot ≈ 103°, Magenta ≈ 50°, Blau ≈ 355°, Cyan ≈ 283°, Grün ≈ 230°.",
  'help.vector.pitfall': "Echte Farbtafeln (z. B. DSC ChromaDuMonde) sind weniger gesättigt als Balken und erreichen die Kästchen erst mit ×2. Die Hautton-Linie (123°) ist gelebte Praxis, kein Normwert.",
  'help.hls.one': "Farbton (HSL) als Winkel, HSL-Sättigung als Abstand zur Mitte.",
  'help.hls.what': "Zeigt die Sättigung unabhängig davon, wie hell eine Farbe ist. Hilft, dunkle oder sehr helle Farben zu beurteilen, die im normalen Vectorscope nahe der Mitte zusammenrücken, und liest sich wie das Vectorscope: Rot liegt an derselben Stelle, die Farbtöne laufen in dieselbe Richtung.",
  'help.hls.read': "Winkel = HSL-Farbton; Rot an der Stelle, an der das Vectorscope Rot für die Matrix der Quelle zeigt, danach Gelb, Grün, Cyan, Blau, Magenta in 60°-Schritten gegen den Uhrzeigersinn (Speichen R, Yl, G, Cy, B, Mg).\nRadius = HSL-Sättigung S = (max − min) / (1 − |max + min − 1|) der R′G′B′-Werte (auf 0–100 % begrenzt); Ringe bei 25/50/75/100 %.\nMitte = unbunt (Grau, Weiß, Schwarz).\nKeine Zielkästchen und keine Hautton-Linie.\nGut: Neutrales in der Mitte; dieselbe Farbe bei verschiedener Helligkeit am selben Radius.",
  'help.hls.try': "Testbild „SMPTE 75 % Balken + PLUGE“.",
  'help.hls.check': "Die sechs Farbbalken liegen auf dem 100-%-Ring, jeweils auf ihrer Speiche (R, Yl, G, Cy, B, Mg); Grau, Weiß und Schwarz liegen in der Mitte. Obwohl die Balken nur 75 % Pegel haben, erreichen sie den äußeren Ring, weil die HSL-Sättigung nicht von der Helligkeit abhängt. (Zwei weitere Punkte auf dem Ring stammen von −I und +Q aus der unteren Reihe.)",
  'help.hls.pitfall': "Nahe Schwarz und Weiß reicht ein winziger Kanalunterschied für hohe HSL-Sättigung; Rauschen in den Tiefen erscheint dann als „gesättigt“. Werte unter 0 % und über 100 % werden vorher abgeschnitten. Für Legalität und Balkenpegel das normale Vectorscope nehmen.",
  'help.cie.one': "Farbort jedes Pixels im CIE 1931 xy oder 1976 u′v′, mit Gamut-Dreiecken.",
  'help.cie.what': "Zeigt, welchen Farbraum das Material tatsächlich nutzt und ob Farben über Rec.709 hinausgehen (HDR/WCG, Kamera-Gamuts). Hilft bei der Prüfung von Konvertierungen (CST, LUT) und Grafiken.",
  'help.cie.read': "Hufeisen = Spektralzug (reine Spektralfarben, mit nm-Beschriftung); Dreiecke Rec.709, P3-D65, Rec.2020, dazu das Gamut der Quelle, wenn es keines davon ist; Kreis bei D65.\nHelligkeit fehlt: Hell und dunkel gleicher Farbe fallen auf denselben Punkt.\nGut: Punkte innerhalb des Zielgamuts; Grau auf D65.",
  'help.cie.try': "Testbild „SMPTE 75 % Balken + PLUGE“.",
  'help.cie.check': "Rot, Grün, Blau liegen genau auf den Ecken des Rec.709-Dreiecks (R x 0,640/y 0,330, G 0,300/0,600, B 0,150/0,060), Gelb, Cyan, Magenta auf dessen Kanten, Grau auf D65 (0,3127/0,3290).",
  'help.cie.pitfall': "75-%- und 100-%-Balken liegen am selben Ort – das Diagramm zeigt keine Pegel. u′v′ (im ⚙ umschaltbar) ist für Farbabstände gleichmäßiger als xy. −I und +Q der unteren Reihe erscheinen als zusätzliche Punkte.",
  'help.diamond.one': "Zwei Rauten nach Tektronix: zeigen R′G′B′-Balance und Gamut-Verstöße je Kanal.",
  'help.diamond.what': "Ideal für Graubalance beim Shading: eine richtig abgeglichene Kamera auf Graukeil oder Weißfläche erzeugt eine senkrechte Linie. Gleichzeitig zeigt die Raute, wie viel Reserve bis zur Gamutgrenze bleibt.",
  'help.diamond.read': "Oben: B′+G′ (senkrecht) über B′−G′ (waagerecht); unten: −(R′+G′) über R′−G′.\nMitte = Schwarz, obere/untere Spitze = Weiß; Grau = senkrechte Linie; gestrichelte innere Raute = 50 %.\nKnick nach links/rechts oben → Blau/Grün-Fehler, unten → Rot/Grün-Fehler; Grünfehler zeigen sich in beiden Rauten.\nAlles Legale liegt innerhalb beider Rauten.\nGut: senkrechte, gerade Linie; nichts außerhalb.",
  'help.diamond.try': "Testbild „Grauverlauf 0–100 %“.",
  'help.diamond.check': "In beiden Rauten eine senkrechte Linie von der Mitte bis zur Spitze.",
  'help.diamond.pitfall': "Hardware-Geräte filtern kurze Überschwinger heraus, lz-scopes nicht: scharfe Kanten können knapp außerhalb erscheinen, ohne dass das Signal im Sinne von R 103 (mit Messfilter) illegal ist.",
  'help.cube.one': "Punktwolke aller Pixel als 3D-Volumen (R′G′B′-Würfel, Y′CbCr, HSV, CIE XYZ, CIELAB, LCh oder ICtCp), frei drehbar.",
  'help.cube.what': "Zeigt das ganze Farbvolumen auf einmal: welche Ecken (Primär-, Sekundärfarben, Weiß, Schwarz) erreicht oder abgeschnitten werden und ob ein Farbstich die Grauachse verschiebt. Nützlich bei LUT- und Konvertierungsprüfung, die Vectorscope und Diamond nur als Projektion zeigen.",
  'help.cube.read': "Drahtgitter = Zielgamut (im R′G′B′-Würfel der 0–100-%-Würfel, dazu ein 25-%-Raster); gestrichelte Grauachse von Schwarz nach Weiß.\nZiehen = drehen, ⇧+ziehen = schieben, Rad oder Pinch = Zoom, Doppelklick = zurücksetzen.\nDer Messpunkt aus dem Bild erscheint als Kreis im Volumen. Optional zeigt der Würfel das Volumen einer geladenen LUT.\nGut: Grau auf der Achse, Farben innerhalb des Gitters.",
  'help.cube.try': "Testbild „SMPTE 75 % Balken + PLUGE“, Raum R′G′B′-Würfel, Messpunkt im Bild auf den gelben Balken.",
  'help.cube.check': "Die Balken liegen auf den Ecken eines kleineren Würfels mit 75 % Kantenlänge (an den 75-Marken der Achsen); der Messpunkt-Kreis sitzt auf der Ecke R′ 75 / G′ 75 / B′ 0.",
  'help.cube.pitfall': "In R′G′B′ ist der Abstand nicht wahrnehmungsgleich; für „wie stark sieht man den Unterschied“ CIELAB/ICtCp und ΔE verwenden (Einstellungen → „ΔE am Messpunkt“, angezeigt im Bild- und im Messwerte-Panel).",
  'help.satlum.one': "Jeder Pixel als Punkt: waagerecht Luma Y′, senkrecht Sättigung |CbCr|.",
  'help.satlum.what': "Zeigt, wo im Helligkeitsbereich Farbe sitzt: gesättigte Lichter (Gefahr für Gamut) oder farbige Schatten (Stich in den Tiefen, z. B. falscher Black Balance). Hilft beim Abgleich von Black und Knee/Low-Key-Saturation.",
  'help.satlum.read': "x = Y′ in % (Bereich wie die Waveform), y = Sättigung |CbCr|/0,5 in %, Skala bis 120 % (100 % ≈ voll gesättigte Primärfarbe).\nUnbunte Pixel liegen unten; Ausbuchtung rechts oben = gesättigte Lichter, links oben = farbige Schatten.\nGut: unten links (Schwarz) und unten rechts (Weiß) keine Punkte in der Höhe.",
  'help.satlum.try': "Testbild „SMPTE 75 % Balken + PLUGE“.",
  'help.satlum.check': "Die Balken liegen zwischen etwa 75 % (Gelb, Blau) und 89 % Sättigung (Grün, Magenta), jeweils bei ihrer Luma (z. B. Gelb bei 69,6 %); Grau, Weiß und Schwarz auf 0 % (Werte aus BT.709 berechnet).",
  'help.satlum.pitfall': "Die Skala ist |CbCr|/0,5 und keine HSL-Sättigung; dunkle Farben haben hier kleine Werte, auch wenn sie „satt“ aussehen.",
  'help.chplot.one': "Zwei Kanäle gegeneinander (R′/G′, R′/B′, G′/B′, Y′/Cb, Y′/Cr, Cb/Cr).",
  'help.chplot.what': "Zeigt Kanalbalance über den ganzen Pegelbereich: Bei Grau liegen R′/G′-Punkte auf der Diagonale. Ein Gamma- oder Black-Fehler eines Kanals erscheint als Kurve oder Versatz – entspricht dem „Tracking“ eines Graukeils.",
  'help.chplot.read': "Gestrichelte Diagonale = gleiche Kanäle (nur bei den R′G′B′-Paaren).\nVersatz parallel zur Diagonale = Black/Pedestal-Fehler; anderer Winkel = Gain-Fehler; Bogen = Gamma-Fehler.\nCb/Cr-Achsen sind −0,50 … +0,50 beschriftet, Mitte = 0.\nGut: Graukeil als gerade Linie auf der Diagonale.",
  'help.chplot.try': "Testbild „Grauverlauf 0–100 %“, Paar R′/G′.",
  'help.chplot.check': "Eine durchgehende Linie genau auf der Diagonale.",
  'help.chplot.pitfall': "Bunte Bildinhalte liegen naturgemäß neben der Diagonale; die Aussage gilt nur für neutrale Vorlagen.",
  'help.minmax.one': "Dunkelstes und hellstes Y′ jeder Bildzeile, von oben nach unten wie im Bild.",
  'help.minmax.what': "Findet schnell Zeilen mit Überschreitungen (Super-White, Sub-Black) und zeigt den Kontrastumfang über die Bildhöhe, z. B. bei Black Shading oder Himmel/Boden-Verläufen.",
  'help.minmax.read': "Senkrecht: Bildzeile (oben = Zeile 1); waagerecht: Y′ −7 … 110 %. Blaue Spur = Minimum, grüne = Maximum.\nGrenzen wahlweise EBU R 103 (−5/105 %, Vorgabe) oder legal (0/100 %) als rote gestrichelte Linien; Überschreitungen färben die Spur rot.\nBis zu vier eigene Ziellinien (⚙, in %).\nGut: keine roten Bereiche; Abstand min–max zeigt Kontrast der Zeile.",
  'help.minmax.try': "Testbild „SMPTE 75 % Balken + PLUGE“, ⚙ Grenzen legal.",
  'help.minmax.check': "Im oberen Bereich min ≈ 5,4 % (Blau) und max ≈ 75 %, unten min = 0 % und max = 100 % (Weißfeld); nichts rot.",
  'help.minmax.pitfall': "Bei R′G′B′-Quellen und Browser-Quellen sind Werte unter 0/über 100 % schon abgeschnitten; Überschreitungen sind nur im Bridge-Modus *16 bit Y′CbCr* und bei Testbildern mit exakten 10-bit-Codes sichtbar.",
  'help.qclog.one': "Zeitgestempelte Liste von Pegel-, Bild- und Tonfehlern aller Live-Quellen.",
  'help.qclog.what': "Läuft während Sendung oder Aufzeichnung mit und hält fest, wann und wie lange etwas schiefging: R-103-Verstoß (−5/105 % und Gesamtbereich 4–1019), Weiß-Clipping, Super-White, Sub-Black, Schwarzbild, Standbild, Tonstille. Export als CSV.",
  'help.qclog.read': "Jede Zeile = ein Ereignis von Beginn bis Ende, mit Uhrzeit, Quell-Timecode und schlimmstem Wert.\nPrüfung viermal pro Sekunde; Schwellen im ⚙ (Vorgaben: Clipping ab 0,5 % der Pixel, Schwarzbild Y′ max < 2 %, Stille < −60 dBFS für 2 s, Standbild 2 s); Ereignistypen einzeln ein- und ausblendbar.\nR 103 meldet erst ab 1 % der Fläche außerhalb −5/105 %.\nGut: leere Liste.",
  'help.qclog.try': "Testbild „Grau 50 %“, für einige Sekunden auf Testbild „Schwarz“ umschalten und zurück.",
  'help.qclog.check': "Ein Ereignis „Schwarzbild“ mit Beginn, Ende und Dauer erscheint.",
  'help.qclog.pitfall': "Standbilder zählen nur bei Live-Quellen und laufenden Dateien, nicht bei Testbildern oder angehaltenen Dateien. R 103 wird nur im Y′CbCr-Pfad geprüft. Testbilder mit 100-%-Weiß (z. B. SMPTE-Balken) lösen bereits „Weiß-Clipping“ aus.",
  'help.timeline.one': "Farbe, Farbton, Sättigung und Luma der letzten 10 s, 1 min oder 5 min als Streifen.",
  'help.timeline.what': "Zeigt Änderungen über die Zeit: Blendensprünge, wandernder Weißabgleich (ATW), Flackern, Lichtwechsel bei Events. Ein „Movie-Barcode“ macht Schnitte und Stimmungen sichtbar.",
  'help.timeline.read': "Waagerecht: Zeit (rechts = jetzt). Oben die mittlere Farbe (Movie-Barcode), darunter Farbtonanteile (hell = viel von diesem Farbton), Sättigung (Mittel und 95 %) und Luma (Bereich min–max, Linie = Mittel).\nAbtastung zehnmal pro Sekunde auf einem 96×54-Raster (feiner wählbar) oder je Bild.\nGut: ruhige, gleichmäßige Streifen, wo das Bild ruhig sein soll.",
  'help.timeline.try': "Zwischen „SMPTE 75 % Balken + PLUGE“ und „Grau 50 %“ hin- und herschalten.",
  'help.timeline.check': "Im Luma- und Sättigungsstreifen erscheinen die Wechsel als scharfe Kanten; bei Grau fällt die Sättigung auf 0.",
  'help.timeline.pitfall': "Der Verlauf wertet immer das ganze Bild aus, ein Messrahmen wirkt hier nicht; ein kleiner, falsch belichteter Bildteil fällt kaum auf – dafür Waveform oder Messwerte mit Messrahmen nehmen.",
  'help.hist.one': "Wie viele Pixel auf welchem Pegel liegen – RGB, Luma oder getrennt.",
  'help.hist.what': "Schneller Überblick über Belichtung und Clipping, ohne Bildposition. Zeigt, ob Lichter oder Tiefen abgeschnitten sind (Stapel am Rand) und wie viel Prozent clippen.",
  'help.hist.read': "Waagerecht: Pegel 0–100 %; senkrecht: Anzahl Pixel (linear oder log).\nOben links der Clipping-Anteil unten (▼) und oben (▲), jeweils der höchste Wert der Kanäle; je Kanal im Panel *Messwerte*.\nDarstellung RGB, Luma oder getrennt; im ⚙ umschaltbar.\nGut: kein hoher Stapel genau bei 0 % oder 100 %, außer im Motiv gewollt.",
  'help.hist.try': "Testbild „Grauverlauf 0–100 %“, Darstellung Luma.",
  'help.hist.check': "Die Verteilung ist über den ganzen Bereich annähernd gleich hoch (flach).",
  'help.hist.pitfall': "Das Histogramm sagt nicht, *wo* im Bild etwas clippt; ein Clipping-Anteil von 0,1 % kann ein Gesicht sein. Mit Zebra oder Waveform gegenprüfen.",
  'help.stats.one': "Zahlen zur Quelle: Format, Y′ min/max/Mittel, Clipping, R 103, MaxCLL/MaxFALL.",
  'help.stats.what': "Liefert die harten Zahlen für Protokoll und Abnahme: ob Pegel im erlaubten Bereich liegen, wie viel Fläche R 103 verletzt, bei PQ-HDR die Content-Light-Level. Zeigt auch Übertragungsweg und verworfene Frames.",
  'help.stats.read': "Y′ min/max/Mittel in % (bei HDR und Log zusätzlich in cd/m² bzw. Szene-%); Clipping je Kanal; MaxCLL/MaxFALL nur bei PQ.\nR 103: Anteil außerhalb −5/105 % (Meldung ab 1 %) und außerhalb 4–1019 (harte Grenze).\nHinweise, wenn die Quelle R′G′B′ (beschnitten) oder Full Range ist.\nGut: Y′ min ≥ −5 %, Y′ max ≤ 105 %, R 103 ohne Warnung.",
  'help.stats.try': "Testbild „SMPTE 75 % Balken + PLUGE“.",
  'help.stats.check': "Y′ max = 100 %, Y′ min = 0 %, Hinweis auf R′G′B′-Quelle (beschnitten). Mit „SMPTE 75 % Balken + PLUGE (LZ)“ (exakte 10-bit-Codes) zeigt Y′ min −2 % durch den PLUGE-Streifen.",
  'help.stats.pitfall': "R 103 ist für Narrow Range definiert; bei Full-Range-Quellen und R′G′B′-Streams ist das Ergebnis nur ein Prozentvergleich (App meldet das).",
  'help.match.one': "Vergleicht Messpunkt oder Rahmenmittel mit einem Ziel oder einer zweiten Kamera.",
  'help.match.what': "Kamera-Matching und CI-Farben: zeigt, wie weit eine Farbe vom Ziel (Kunden-Hex, Logo) oder vom selben Objekt in einer anderen Kamera entfernt ist, und übersetzt die Korrektur in Kamera-Begriffe (Multi-Matrix, Weißabgleich) und Resolve-Werte.",
  'help.match.read': "Farbfelder nebeneinander; ΔE00 (SDR) bzw. ΔITP (HDR), dazu ΔL/ΔC/ΔH, Farbton, Sättigung.\nAmpel: grün bis ΔE 1 (eben merklich), gelb bis zur eingestellten Toleranz, darüber rot; ΔE00 ≈ 1 ist eine Faustregel, keine feste Schwelle.\nKorrekturvorschlag in Worten und Werten.\nGut: ΔE00 nahe 0, ΔH nahe 0 (Farbton stimmt).",
  'help.match.try': "Testbild „SMPTE 75 % Balken + PLUGE“, im Bild-Panel Messpunkt auf den gelben Balken; im ⚙ des Farbabgleichs „+ Messpunkt“, dann unter „Vergleich mit“ dieses Ziel wählen.",
  'help.match.check': "ΔE00 ≈ 0, Urteil „kaum unterscheidbar“; mit dem Messpunkt auf dem Cyan-Balken ein großer Wert und „deutlich verschieden“.",
  'help.match.pitfall': "Kamera-Matching ist nur unter gleichem Licht auf derselben Tafel verlässlich; Einstellungen einfach von Kamera zu Kamera kopieren reicht nicht. Multi-Matrix verschiebt angrenzende Farbbereiche mit.",
  'help.tiles.one': "Derselbe Scope für bis zu acht Quellen nebeneinander, jede Kachel mit Kamera-ID.",
  'help.tiles.what': "Kamera-Matching auf einen Blick: alle Kameras auf derselben Waveform, Parade oder demselben Vectorscope, Schwarz, Weiß und Farbe lassen sich vergleichen, ohne die Quelle umzuschalten. Im ⚙ Scope und Quellen wählen; nichts angehakt zeigt die ersten acht Videoquellen.",
  'help.tiles.read': "Leiste über jeder Kachel: Nummer in der Quellenliste und Name der Quelle.\nAlle Kacheln nutzen dieselben Einstellungen (Helligkeit, Farben, Zoom, Referenzspur).\nGut: Abgeglichene Kameras haben in jeder Kachel dieselbe Spurhöhe und -form.",
  'help.tiles.try': "Eine zweite Testbild-Quelle anlegen („+ Quelle“ → „Testbild“, „Graustufen 11 (0–100 %)“), die erste auf „SMPTE 75 % Balken + PLUGE“ lassen, dann „Waveform Luma“ als Kachel-Scope wählen.",
  'help.tiles.check': "zwei Kacheln mit 1 und 2: Kachel 1 zeigt die Balkenpegel, Kachel 2 die elf Graustufen von 0 bis 100 %.",
  'help.tiles.pitfall': "Jede Kachel ist klein: Feine Pegelunterschiede liest man besser mit der Referenzspur (⚙ → Referenz) als durch Vergleich der Kacheln mit dem Auge.",
  'help.noise.one': "Zufallsrauschen von Y′, R′, G′ und B′ im Messrahmen: Pegel, σ in %, mVrms und dB, dazu S/N.",
  'help.noise.what': "Vergleicht Kameras und Gain-Stufen: Schwarzrauschen mit Objektivdeckel, Bildrauschen auf gleichmäßigem Grau. Eine Kamera mit mehr Gain oder lauterem Sensor fällt sofort auf, auch markenübergreifend.",
  'help.noise.read': "σ = Effektivwert der Abweichung vom Mittel (mit „Shading abziehen“ von einer angepassten Fläche, damit Objektiv-Shading nicht mitzählt).\ndB = 20·log10(σ / 100 %); −50 dB = 0,32 %. S/N = der Betrag davon.\nDie Quantisierungsgrenze zeigt, wie tief dieser Signalweg überhaupt messen kann (8 bit ≈ −59 dB, 10 bit narrow ≈ −70 dB).\nGut: abgeglichene Kameras bei gleichem Gain innerhalb von etwa 1 dB.",
  'help.noise.try': "Testbild „Grau 50 %“, kein Messrahmen.",
  'help.noise.check': "Pegel 50,2 % in allen Kanälen und σ 0,00 / −∞ dB: Testbilder rauschen nicht. Mit einer Kamera zeigt dieselbe Messung mit Objektivdeckel ihr Schwarzrauschen.",
  'help.noise.pitfall': "Ein skaliertes Analysebild mittelt Rauschen weg; Bridge-Ströme in Breite „nativ“ messen. Kanten oder Struktur im Rahmen zählen als Rauschen – den Rahmen auf eine ebene Fläche legen.",
  'help.wshading.one': "Ebenheit von Y′ und jedem Farbkanal über eine weiße Fläche, als Karte und zerlegt in Sägezahn und Parabel, horizontal und vertikal.",
  'help.wshading.what': "White Shading: Objektive und Prismen machen die Mitte heller als die Ränder oder färben eine Seite. Die Werte sagen, an welchem Kamera-Regler man dreht – je Kanal erst Saw H/V, dann Par H/V –, bis die Fläche eben ist.",
  'help.wshading.read': "Karte: Abweichung jeder Zelle vom Mittel der Fläche (warm = heller, blau = dunkler) oder Farbstich R′−G′ / B′−G′.\nSaw H = rechter − linker Rand, Saw V = unten − oben, Par = Rand − Mitte, in % des Mittels; Spanne = Max − Min der angepassten Fläche.\nGut: alle Werte innerhalb weniger Zehntelprozent, Farbstich-Karte neutral.",
  'help.wshading.try': "Testbild „Grauverlauf 0–100 %“, Karte Y′.",
  'help.wshading.check': "Saw H groß und positiv (die Rampe steigt nach rechts), Saw V und beide Par nahe 0; mit „Grau 50 %“ ist jeder Wert 0.",
  'help.wshading.pitfall': "Die Fläche muss wirklich gleichmäßig sein: ein Hotspot der Leuchte oder ein schräger Diffusor erscheint als Objektiv-Shading. Rahmen frei von Struktur halten und leicht unscharf stellen.",
  'help.skinall.one': "Die Hauttöne mehrerer Kameras als farbige Punktwolken in einem Vectorscope, jede mit Mitte, Farbton und Sättigung.",
  'help.skinall.what': "Gesichter über Kameras hinweg abgleichen: Dieselbe Moderatorin aus verschiedenen Winkeln sollte überall denselben Hautfarbton und dieselbe Sättigung haben. Pixel-für-Pixel-Vergleich scheitert an verschiedenen Ausschnitten, der Vergleich der Hautverteilungen nicht. Die Gesichter kommen aus der Gesichtserkennung (⚙ „Gesichter suchen“).",
  'help.skinall.read': "Eine Farbe je Quelle; Punkte = Hautpixel, Kreuz = ihre Mitte.\nH = Farbtonwinkel (Hauttonlinie 123°) mit dem Abstand zur Linie; S = Sättigung; ΔH/ΔS gegen die Referenzkamera.\nGut: alle Kreuze übereinander, ΔH innerhalb von etwa ±2°.",
  'help.skinall.try': "Testbild „ColorChecker (Näherung)“, einen Messrahmen über die beiden Hautfelder oben links ziehen.",
  'help.skinall.check': "zwei dichte Häufungen auf der Hauttonlinie (die Felder liegen bei 122,2° und 123,3°, Sättigung 16 % und 22 %), das Kreuz bei etwa 123°; ohne Rahmen zieht das orange Feld bei 136,9° das Kreuz von der Linie weg.",
  'help.skinall.pitfall': "Das Licht auf dem Gesicht unterscheidet sich je Kamerawinkel (Führungs- gegen Aufhellseite); Kameras auf derselben Gesichtsseite vergleichen und die Gesichtserkennung in jeder Quelle einschalten.",
  'help.chart.one': "Eine Farbtafel in jeder Kamera, Feld für Feld gegen die Referenzkamera verglichen, mit einer Matrix, die jede Kamera auf die Referenz bringen würde.",
  'help.chart.what': "Kameras an einem Objekt abgleichen, das alle sehen: ein ColorChecker Classic vor jeder Kamera. Die Tafel wird über vier Ecken gefunden (geklickt, Messrahmen oder ganzes Bild), deshalb stören verschiedene Winkel und Größen nicht.",
  'help.chart.read': "Ein Block je Kamera, 6 × 4 Zellen in der Anordnung der Tafel; jede Zelle ist das ΔE00 (ΔITP bei PQ/HLG) dieses Felds gegen dasselbe Feld der Referenz.\nMittel und Maximum über den Zellen; darunter die 3×3-Matrix (Zeilen R, G, B, lineares Licht) mit ΔE vorher → nachher.\nGut: alle Zellen grün (ΔE ≤ 1), Mittel unter der Toleranz.",
  'help.chart.try': "Zwei Testbild-Quellen, beide „ColorChecker (Näherung)“; Panel ohne Ecken (die Tafel füllt das Bild).",
  'help.chart.check': "Beide Blöcke ganz grün mit ΔE 0,0; eine Quelle auf ein anderes Testbild stellen, dann werden ihre Zellen rot.",
  'help.chart.pitfall': "Das Licht auf der Tafel muss für alle Kameras gleich sein (kein Schatten, keine Spiegelung aus einem Winkel); ein Feld mit Reflex verzieht die Matrix. Die Matrix wird berechnet, nicht angewandt: in der Kamera oder einer CST eintragen.",
  'help.drift.one': "Schwarzboden und Neutralbalance jeder Kamera gegen das Mittel aller Kameras, mit Alarm, wenn eine wegdriftet.",
  'help.drift.what': "Eine abgeglichene Kameragruppe während der Show beobachten: LED-Licht, Wolken oder eine warm werdende Kamera schieben eine Kamera von den anderen weg. Der Wächter vergleicht jede Kamera mit der Gruppe, nicht mit einem festen Sollwert.",
  'help.drift.read': "Eine Zeile je Kamera: Schwarz (Y′-Schwarzschwerpunkt in %), Δ Schwarz, ΔR−G und ΔB−G des Medians gegen das Gruppenmittel, alles in Prozentpunkten.\nGrün = innerhalb der Toleranz, rot = abgedriftet.\nGut: alle Zeilen grün, Abweichungen nahe 0.",
  'help.drift.try': "Zwei Testbild-Quellen mit demselben Testbild, dann eine auf ein anderes umstellen; oder der Shading-Simulator neben einem Testbild und Touch Shading auf dem Simulator.",
  'help.drift.check': "Gleiches Testbild: jedes Δ 0,0 und grün. Master Black des Simulators anheben: seine Zeile wird rot mit positivem Δ Schwarz.",
  'help.drift.pitfall': "Die Kameras müssen vergleichbaren Inhalt sehen: eine dunkle Totale gegen eine helle Nahe ist keine Drift. Messrahmen auf dasselbe graue Objekt machen den Vergleich fair.",
  'help.audio-meter.one': "Sample-Peak, True Peak und Lautheit (M, S, I, LRA) nach EBU R 128.",
  'help.audio-meter.what': "Pegel und Lautheit für Sendung und Stream einhalten: Programm auf −23 LUFS, Spitzen nicht über −1 dBTP. Zeigt auch Übersteuerungen und den Ausrichtungspegel −18 dBFS.",
  'help.audio-meter.read': "Balken je Kanal: Sample-Peak (100 ms), weiße Marke = True Peak, Peak-Hold 3 s; Marken bei −18 dBFS (R 68) und −1 dBTP (R 128).\nM (400 ms), S (3 s), I (integriert, gegated) auf Skala EBU +9 oder +18, absolut LUFS oder relativ LU (0 LU = −23 LUFS).\nLRA in den ersten 60 s als „unstabil“ markiert.\nGut: I = −23,0 LUFS (±0,5 LU; ±1 LU bei Live-Programmen, wo enger nicht erreichbar), Max TP ≤ −1 dBTP.",
  'help.audio-meter.try': "Tongenerator: Sinus 1 kHz, Stereo, −18 dBFS, „→ als Messquelle“.",
  'help.audio-meter.check': "Peak −18 dBFS auf beiden Kanälen; M und S zeigen den Wert, den der Generator als Soll anzeigt (für diesen Stereo-Sinus etwa −18 LUFS = +5 LU).",
  'help.audio-meter.pitfall': "dBFS (Spitzenpegel) und LUFS (Lautheit) sind verschiedene Größen; ein Programm kann bei −1 dBTP trotzdem viel zu laut oder zu leise sein.",
  'help.audio-loudness.one': "Momentary- und Short-term-Lautheit der letzten 1 bis 60 Minuten mit Zielband.",
  'help.audio-loudness.what': "Zeigt, ob ein Programm über die Zeit gleichmäßig im Ziel bleibt, und wo laute Einspieler, Applaus oder zu leise Moderation lagen. True-Peak-Überschreitungen sind markiert.",
  'help.audio-loudness.read': "Waagerecht: Zeit; senkrecht: Lautheit; Zielband ±1 LU um den Zielwert.\nMarken bei True Peak > −1 dBTP.\nGut: S-Kurve überwiegend im Band, keine Peak-Marken.",
  'help.audio-loudness.try': "Generator Sinus −23 dBFS Stereo, nach einer Minute auf −18 dBFS umschalten.",
  'help.audio-loudness.check': "Die Kurve springt um 5 LU nach oben und verlässt das Zielband.",
  'help.audio-loudness.pitfall': "Short-term-Werte schwanken bei Sprache stark; maßgeblich für R 128 ist die integrierte Lautheit I über das ganze Programm.",
  'help.audio-spectrum.one': "Frequenzverteilung des Tons per FFT, logarithmische Frequenzachse.",
  'help.audio-spectrum.what': "Findet Brummen (50/100 Hz), Pfeifen, Rückkopplungen und fehlende Höhen; prüft Messtöne und Leitungen.",
  'help.audio-spectrum.read': "Waagerecht: Frequenz (log), senkrecht: Pegel in dB.\nNeigung 0/3/4,5 dB/Okt. gleicht die natürliche Abnahme aus; Terzbänder wahlweise.\nGut: keine schmalen, stehenden Spitzen, die nicht zum Programm gehören.",
  'help.audio-spectrum.try': "Generator Sinus 1 kHz.",
  'help.audio-spectrum.check': "Eine einzelne Spitze bei 1 kHz. Dann rosa Rauschen mit Neigung 3 dB/Okt. als Linie:",
  'help.audio-spectrum.pitfall': "Die FFT-Größe bestimmt die Auflösung: kleine FFT trennt tiefe Frequenzen schlecht, große reagiert träge.",
  'help.audio-phase.one': "Stereobild als M/S-Darstellung mit Korrelationsgradmesser.",
  'help.audio-phase.what': "Prüft Stereo-Breite, Mono-Kompatibilität und Verpolung. Ein verpolter Kanal kann bei Mono-Abhöre (Handy, Radio) Sprache auslöschen.",
  'help.audio-phase.read': "Senkrechte Linie = Mono (L = R); L links oben, R rechts oben.\nWaagerechte Linie = gegenphasig (L = −R).\nKorrelation: +1 = mono, 0 = unabhängig, −1 = gegenphasig.\nGut: Wolke eher senkrecht, Korrelation überwiegend positiv.",
  'help.audio-phase.try': "Generator Sinus, Schnellwahl L+R.",
  'help.audio-phase.check': "senkrechte Linie, Korrelation +1. Dann L−R:",
  'help.audio-phase.pitfall': "Kurzzeitig negative Korrelation kommt bei breiten Hallanteilen vor; erst dauerhaft negative Werte deuten auf Verpolung. Der Korrelationsgrad ist nicht frei zugänglich genormt (Fenster 600 ms ist eigene Festlegung).",
  'help.audio-check.one': "Erkennt Leitungs-Idents, meldet Kanalfehler und misst den Ton-Bild-Versatz.",
  'help.audio-check.what': "Leitungsprüfung vor der Sendung: kommen alle Kanäle in der richtigen Reihenfolge, Polarität und mit −18 dBFS an? Dazu Lippensynchronität zwischen Blitz und Piep.",
  'help.audio-check.read': "Erkannt: EBU-Stereo-Ident (R 49), GLITS, BLITS, EBU-Mehrkanal-Ident (Tech 3304), eigener Kanal-Ident.\nMeldungen: „L/R vertauscht“, „Polarität invertiert“, „Kanal fehlt“, falsche Kanalfolge, Pegel gegen −18 dBFS.\nA/V-Versatz positiv = Ton vor dem Bild; Bewertung nach BT.1359-1: wahrnehmbar ab etwa +45/−125 ms, akzeptabel bis etwa +90/−185 ms.\nGut: keine gelbe oder rote Meldung, Versatz im Bereich +25/−100 ms.",
  'help.audio-check.try': "Tongenerator „EBU-Stereo-Ident“, Pegel −18 dBFS, „→ als Messquelle“.",
  'help.audio-check.check': "„EBU-Stereo-Ident (R 49)“ erkannt, Meldungen nur grün (L/R richtig zugeordnet, gleichphasig, Pegel −18 dBFS). Dann Schnellwahl R statt L+R:",
  'help.audio-check.pitfall': "Der A/V-Versatz gilt nur für die gemessene Strecke; ohne einmalige Kalibrierung ist die Bildausgabe des Rechners selbst nicht garantiert synchron.",
  'help.genlock.one': "Status des Haustakts am Referenzeingang einer DeckLink-Karte, dazu Bildtakt-Lage und Timecode.",
  'help.genlock.what': "In Mehrkamera-Systemen müssen alle Kameras und Zuspieler auf denselben Takt gelockt sein, sonst springt das Bild beim Umschalten. Das Panel zeigt, ob die Referenz anliegt und gelockt ist.",
  'help.genlock.read': "Lock-Status, erkanntes Format (Black Burst bei SD, Tri-Level bei HD), eingestellter Genlock-Offset, Eingangsstatus.\nLage des Bildtakts von DeckLink-/NDI-Quellen im SMPTE-ST-2059-1-Raster (Lage, Streuung, Drift in ppm).\nGut: „gelockt“, passendes Format, Drift nahe 0 ppm.",
  'help.genlock.try': "Tri-Level-Sync an den Referenzeingang der DeckLink legen.",
  'help.genlock.check': "Referenz „gelockt“, Format „Tri-Level-Sync (HD-Format)“. Ohne Kabel: „nicht gelockt“.",
  'help.genlock.pitfall': "Das DeckLink-SDK meldet den Zeitversatz zwischen Eingang und Referenz nicht; das Panel zeigt daher keine Timing-Messung wie ein Hardware-Scope. Mit Hardware noch ungeprüft.",
  'help.clock.one': "Tageszeit-Timecode, Quell-Timecode, LTC und PTP-Status.",
  'help.clock.what': "Zeitbezug für Sendung und Aufzeichnung: Abgleich von Kamera-Timecode mit der Tageszeit, Lesen von LTC aus dem Ton, Prüfen eines PTP-Grandmasters (ST 2110/2059).",
  'help.clock.read': "Tageszeit nach ST 2059-1 (Systemzeit → TAI → Timecode); „Systemuhr – keine Referenz“, solange kein PTP korrigiert.\nQuell-Timecode (Container-Start-Tag oder SEI über die Bridge, Videodateien im Browser ab 0) und Differenz zur Tageszeit in Frames.\nPTP: Grandmaster, Domain, clockClass, Offset (Software-Schätzung).\nGut: Differenz 0 Frames, PTP empfangen.",
  'help.clock.try': "Panel „Uhr / Timecode“ öffnen, ohne PTP im Netz.",
  'help.clock.check': "Der Tageszeit-Timecode läuft und ist als „Systemuhr – keine Referenz“ gekennzeichnet; bei laufender Bridge meldet die PTP-Zeile „kein PTP empfangen“.",
  'help.clock.pitfall': "Über 30 fps zählt der Timecode 0…49/59 wie Schnittprogramme; LTC kennt nach ST 12-1 nur Frame-Paare. Software-Zeitstempel sind für PTP nur eine Schätzung.",
  'help.light-cie.one': "Gemessener Farbort der Lichtquelle im CIE 1976 u′v′ oder 1931 xy mit Planck-Kurve.",
  'help.light-cie.what': "Zeigt, ob eine Leuchte auf der Planck-Kurve (Glühlicht/Tageslicht-Charakter) liegt oder einen Grün-/Magentastich hat. Grundlage, um Leuchten verschiedener Hersteller vor dem Kameraweißabgleich anzugleichen.",
  'help.light-cie.read': "Planck-Kurve mit Isothermen (CCT), Linien Duv ±0,01/±0,02.\nOberhalb der Kurve (Duv > 0) = grünlich, unterhalb (Duv < 0) = magenta.\nSpur je Gerät (aktuell oder 20/60/300 Messungen), gespeicherte Messpunkte, Δu′v′ zum gewählten Ziel (Referenzpunkt, 3200/4300/5600/6500 K Planck, D65).\nGut: Punkt auf oder sehr nahe der Kurve, alle Leuchten nah beieinander.",
  'help.light-cie.try': "Opple erst unter eine Halogen-/Kunstlichtleuchte, dann ins Tageslicht halten.",
  'help.light-cie.check': "Der Punkt wandert in Richtung der Planck-Kurve zu höherer CCT (von den niedrigen Isothermen um 3000 K zu denen um 5000–6500 K).",
  'help.light-cie.pitfall': "Zwei Lichter mit gleicher CCT können verschieden aussehen, wenn ihr Duv verschieden ist; immer beides prüfen.",
  'help.light-vector.one': "Farbabweichung des Lichts von einem Zielweiß als Winkel und Abstand (CIELUV).",
  'help.light-vector.what': "Lichtabgleich am Set: zeigt, in welche Richtung (wärmer, kälter, grün, magenta) und wie weit eine Leuchte vom Ziel abweicht, und schlägt ab 5 mired Abweichung eine CTO/CTB-Folie vor (Lee oder Rosco).",
  'help.light-vector.read': "Mitte = Zielweiß (3200/4300/5600/6500 K, D65 oder Referenzpunkt).\nWinkel = Farbton h_uv, Abstand = Sättigung s_uv = 13·Δu′v′.\nRichtungswörter wärmer/kälter entlang der Planck-Kurve, grün/magenta quer dazu.\nMired zum Ziel und Folienvorschlag (nicht bei Ziel D65).\nGut: Punkt in der Mitte; unter 5 mired Abweichung schlägt die App keine Folie mehr vor.",
  'help.light-vector.try': "⚙ Mitte (Ziel) „5600 K Planck“, Opple unter eine 3200-K-Leuchte.",
  'help.light-vector.check': "Punkt Richtung „wärmer“, „Mired zum Ziel“ etwa −134 (10⁶/5600 − 10⁶/3200) mit CTB-Vorschlag.",
  'help.light-vector.pitfall': "Folien korrigieren nur die Farbtemperatur in Mired, nicht ein lückenhaftes Spektrum; eine LED kann nach Folie „richtig“ messen und an der Kamera trotzdem falsch wirken.",
  'help.light-bands.one': "Kalibrierte Zählwerte der 6 bzw. 8 Farbfilter des Opple-Sensors, keine spektrale Leistung.",
  'help.light-bands.what': "Grober Blick auf die spektrale Zusammensetzung: zeigt etwa, ob einer LED Rot- oder Cyan-Anteile fehlen. Ergänzt CCT und Duv, die allein nichts über Lücken sagen.",
  'help.light-bands.read': "Je Filterkanal ein Balken, relativ zum stärksten Kanal; wahlweise als Verhältnis zum Referenzpunkt (×1 = gleich).\nGut: zwei Lichter mit ähnlichem Balkenprofil verhalten sich an der Kamera ähnlicher.",
  'help.light-bands.try': "Glühlicht messen, in der Seitenleiste als Messpunkt aufnehmen und als Referenz (A) markieren, dann eine weiße LED messen.",
  'help.light-bands.check': "Die Balkenprofile unterscheiden sich sichtbar; das Referenzprofil erscheint gestrichelt daneben.",
  'help.light-bands.pitfall': "Das ist kein Spektrum; 6–8 Stützstellen können schmale Spitzen oder Lücken nicht auflösen.",
  'help.light-trend.one': "Lux, CCT und Duv über 30 s, 2 min, 10 min oder 1 h, mit Mittel und Streuung.",
  'help.light-trend.what': "Zeigt Drift und Schwankung: Aufwärmen von Leuchten, wechselndes Tageslicht, Dimmer-Effekte. Hilft zu entscheiden, wann Weißabgleich nachgeführt werden muss.",
  'help.light-trend.read': "Kurven für Lux, CCT, Duv (einzeln oder zusammen); je Größe Mittel und σ, bei Lux zusätzlich der Variationskoeffizient in %.\nGut: flache Kurven, kleine Streuung.",
  'help.light-trend.try': "Opple 2 Minuten vor eine frisch eingeschaltete Leuchte legen.",
  'help.light-trend.check': "Aufwärm-Drift in CCT oder Lux ist als Kurve sichtbar, danach flach.",
  'help.light-trend.pitfall': "Flimmern wird hier nicht gemessen (Light Master 4/Flimmern ungeprüft); eine ruhige Kurve heißt nicht flimmerfrei.",
  'help.light-map.one': "Punkte nacheinander in ein Raster aufnehmen: Gleichmäßigkeit von Helligkeit und Farbe.",
  'help.light-map.what': "Prüft, wie gleichmäßig eine Fläche ausgeleuchtet ist (Green Screen, Bühne, Ambi-Fläche für White Shading) und vergleicht zwei Lichter mit Mired und Grün/Magenta-Richtung.",
  'help.light-map.read': "Raster mit Messpunkten als Karte: Beleuchtungsstärke in % vom hellsten Punkt, Δu′v′ zum Mittel (Skala 0 … 0,01) oder CCT zum Mittel (±500 K); Kopfzeile mit Gleichmäßigkeit min/max in % und max Δu′v′.\nRastergröße, Aufnahme und Vergleich zweier Lichter (Mired, Grün/Magenta mit Lee-Folienvorschlag) in der Seitenleiste → Lichtmesser.\nGut: Gleichmäßigkeit nahe 100 %, Δu′v′ klein.",
  'help.light-map.try': "Seitenleiste → Lichtmesser → Messfeld 3×3, die neun Punkte auf einer Wand nacheinander aufnehmen (blauer Rahmen = nächster Punkt).",
  'help.light-map.check': "Kopfzeile „9/9 Punkte“ mit Gleichmäßigkeit und max Δu′v′.",
  'help.light-map.pitfall': "Für White Shading muss die Fläche sehr gleichmäßig sein; Tektronix nennt ±0,5 % als typisch, 1 % und mehr als häufig – Abweichungen der Fläche landen sonst als „Shading-Fehler“ in der Kamera.",
  'help.light-spectrum.one': "Beim Opple die Filterkanäle über der Wellenlänge, bei Spektrometern das echte Spektrum.",
  'help.light-spectrum.what': "Mit einem Spektrometer (über ArgyllCMS) lässt sich die spektrale Qualität einer Leuchte beurteilen, die über Hautwiedergabe und Kamera-Matching entscheidet; dazu CRI/TLCI/TM-30, wie ArgyllCMS sie berechnet.",
  'help.light-spectrum.read': "Waagerecht: Wellenlänge 380–780 nm, senkrecht: relativer Wert (Spitze = 100 %).\nGut: möglichst lückenlose, gleichmäßige Kurve; tiefe Täler deuten auf schlechte Farbwiedergabe.",
  'help.light-spectrum.try': "Seitenleiste → Lichtmesser → Weitere Messgeräte → „Spektrum-Datei öffnen …“ (Argyll .sp oder CSV mit Wellenlänge, Wert).",
  'help.light-spectrum.check': "Kurve erscheint über der Wellenlängenachse, Kopfzeile mit Bereich und Spitze in nm.",
  'help.light-spectrum.pitfall': "Mit dem Opple ist das kein Spektrum, nur Filterstützstellen; CRI/TLCI daraus nicht ableiten.",
  'help.light-swatch.one': "Zeigt den gemessenen Farbort des Lichts als Farbfläche auf dem Display.",
  'help.light-swatch.what': "Macht eine Messung anschaulich: Team und Kunde sehen, wie warm, kalt oder grünlich ein Licht ist, neben dem Planck-Ort gleicher CCT als Vergleich.",
  'help.light-swatch.read': "Fläche „gemessen (mit Duv)“ in Display-Farben (sRGB oder P3, Helligkeit normiert), daneben „Planck, gleiche CCT“ → der Unterschied ist der Duv-Anteil.\nSchraffur = außerhalb des Display-Gamuts, gezeigt wird die abgeschnittene Farbe.\nGut: Fläche und Planck-Vergleich sehen gleich aus (Duv ≈ 0).",
  'help.light-swatch.try': "Licht mit sichtbarem Grünstich messen.",
  'help.light-swatch.check': "Fläche wirkt grünlicher als die Planck-Vergleichsfläche daneben.",
  'help.light-swatch.pitfall': "Die Darstellung hängt vom Display und dessen Kalibrierung ab; sie ist eine Veranschaulichung, keine Messung.",
  'help.simulcast.one': "Heatmap, wie weit das gewandelte Bild (z. B. SDR aus HDR) vom echten abweicht, als ΔE ITP.",
  'help.simulcast.what': "Im HDR/SDR-Simulcast sehen die meisten Zuschauer die SDR-Wandlung. Das Panel vergleicht zwei Stufen der Kette einer Quelle – das HDR-Signal und das Bild nach CST/LUT – beide als Displaylicht, SDR zurückgesetzt mit 100 % = 203 cd/m², und färbt jede Stelle nach ΔE ITP (ITU-R BT.2124). Es zeigt, wo die Wandlung Lichter, Farbe oder Schattenzeichnung verliert.",
  'help.simulcast.read': "Grau = unter 1, nicht sichtbar; blau → gelb → rot bis zur Skala, darüber weiß.\nOben links: Mittel, 95. Perzentil und Maximum, Anteil über 1 und über der gewählten Grenze.\nStufen im ⚙: Referenz (echtes Bild) und die verglichene.\nGut: grau, wo das Bild wichtig ist; Farbe nur in Lichtern über SDR-Weiß.",
  'help.simulcast.try': "Testbild „PQ-Verlauf mit Referenzweiß 203“, in der Seitenleiste unter CST / LUT eine CST nach Rec.709 / BT.1886 mit Tone Mapping „Clip an der Zielspitze“; Stufen im Panel „Signal“ und „nach CST“.",
  'help.simulcast.check': "der Verlauf bleibt bis etwa 203 cd/m² grau und färbt sich nach rechts (beschnittene Lichter); das untere Feld bei 203 cd/m² bleibt grau.",
  'help.simulcast.pitfall': "ΔE ITP setzt die kritischste Adaptation voraus: Werte von 1–3 sind im normalen Wohnzimmer selten sichtbar. Log-Stufen sind Szenenlicht und geben nur eine Rangfolge, keine Sichtbarkeit.",
  'help.encoder.one': "Programm gegen Rücklauf eines Streams: Verzögerung, Blockbildung, Banding und A/V-Versatz, live.",
  'help.encoder.what': "Kleine Produktionen streamen ohne Monitoring-Kette. Den dekodierten Stream (HLS, RTMP, SRT) als Quelle anlegen, in diesem Panel zeigen und im ⚙ das Programm wählen (was in den Encoder geht). Das Panel vergleicht beide laufend und zeigt, was Encoder und Strecke hinzufügen.",
  'help.encoder.read': "Verzögerung: wie weit der Rücklauf hinterherläuft, mit der Sicherheit der Zuordnung (bewegter Inhalt nötig).\nBlockbildung B/A: Sprünge über die 8-Pixel-Blockgrenzen gegen die innerhalb der Blöcke; 1 = keine Blockstruktur. Programm → Rücklauf.\nBanding: Index nach CAMBI (vereinfacht); höher = mehr Stufen in flachen Verläufen.\nA/V: Versatz jeder Quelle aus Blitz und Piep und die Differenz, die die Strecke hinzufügt (BT.1359-1).\nGut: Rücklauf in jeder Zeile nahe am Programm.",
  'help.encoder.try': "Zwei Quellen: das Testbild „A/V-Sync“ mit dem Generator-Piep als Programm, dasselbe Signal per ffmpeg durchgereicht (oder ein RTSP-Teststream) als Rücklauf. Panel-Quelle = Rücklauf, im ⚙ Programm = das Testbild.",
  'help.encoder.check': "sobald sich das Bild bewegt, erscheint eine Verzögerung; die A/V-Zeile zeigt beide Versätze und ihre Differenz.",
  'help.encoder.pitfall': "Blockbildung misst nur bei nativer Analysebreite (Bridge-Breite „nativ“); ein skaliertes Analysebild verschmiert das 8-Pixel-Raster.",
  'help.lens.one': "White Shading und Mittenfarbe des Objektivs auf einer gleichmäßigen Weißfläche, gespeichert je Objektiv und Zoom und nach einem Objektivwechsel verglichen.",
  'help.lens.what': "Jedes Objektiv schattiert anders (Randabfall, Grün/Magenta oben und unten, eine eigene Farbe), und das ändert sich mit dem Zoom. Kameras halten die Korrekturen in Lens Files; dieses Panel misst das Bild: Säge und Parabel je Kanal, die Mittenfarbe als R/G und B/G, gespeichert als Fingerabdruck. Nach einem Objektivwechsel zeigt es, was vom gespeicherten Fingerabdruck abweicht und welcher Regler zu drehen ist.",
  'help.lens.read': "Karte: Helligkeit jeder Fläche gegen die Mitte (blau dunkler, orange heller, ±10 %).\nTabelle: Säge H/V und Parabel H/V je Kanal in % der Mitte, Rest = was die vier Terme nicht erklären.\nΔ-Zeilen: live minus gespeichert in Prozentpunkten; die größte wird genannt.\nGut: Δ nahe 0, Rest klein.",
  'help.lens.try': "Kamera auf eine gleichmäßig beleuchtete Weißkarte oder einen Diffusor (bildfüllend, leicht unscharf), im ⚙ Objektiv und Zoom eintragen, „Fingerabdruck speichern“. Hineinzoomen, einen zweiten speichern, dann zurückzoomen.",
  'help.lens.check': "zurück am ersten Zoom wählt das Panel diesen Fingerabdruck, und die Δ-Zeilen liegen nahe 0.",
  'help.lens.pitfall': "Ungleichmäßiges Licht sieht aus wie Objektiv-Shading – die Fläche muss auf Bruchteile eines Prozents gleichmäßig sein (Tektronix: ±0,5 % mit Diffusor üblich).",
  'help.shguide.one': "Geführter Shading-Ablauf mit Live-Messung: Schwarz, Black Balance, Flare, Graukeil, Weiß, Knie, Matrix – dazu die Kameradaten des Touch-Shading-Ziels.",
  'help.shguide.what': "Für alle, die ohne Mentor shaden: Jeder Schritt sagt, was vors Objektiv gehört, misst den Messrahmen und nennt den Regler und die Richtung.",
  'help.shguide.read': "Y′ und R′−G′ / B′−G′ im Messrahmen; Knie: Spitze und geclippter Anteil im ganzen Bild; Flare: ΔY′ und Farbverschiebung zwischen Schwarz bei Blende zu und offen.",
  'help.shguide.try': "Testbild „Schwarz“, Schritt 1, dann „Grau 50 %“ für Schritt 4.",
  'help.shguide.check': "Mit „Schwarz“ zeigt Schritt 2 ✓ (R′−G′ und B′−G′ +0,0 %); mit „Grau 50 %“ zeigt Schritt 4 Y′ etwa 50 % und ✓.",
  'help.shguide.pitfall': "Der Flare-Schritt braucht ein wirklich schwarzes Objekt; ein dunkles Grau erscheint als Flare.",
  // --- end scope texts ---
} satisfies Translation<typeof en>;
